insert into public.glossary_terms (slug, term, term_bn, explain_en, explain_bn, source_url, last_verified, is_sample, published, origin) values
  ('ects', 'ECTS', 'ইসিটিএস', 'European credit points. One year of full-time study is 60 ECTS, so a 2-year master''s is usually 120 ECTS.', 'ইউরোপের ক্রেডিট পদ্ধতি। এক বছরের পূর্ণকালীন পড়াশোনা ৬০ ইসিটিএস, তাই ২ বছরের মাস্টার্স সাধারণত ১২০ ইসিটিএস।', 'https://example.org/sample/glossary/ects', '2026-08-24', true, true, 'sample'),
  ('moi', 'MOI (Medium of Instruction letter)', 'এমওআই (মিডিয়াম অব ইনস্ট্রাকশন চিঠি)', 'A letter from your university saying your degree was taught in English. Some programs accept it instead of IELTS.', 'আপনার বিশ্ববিদ্যালয়ের চিঠি, যেখানে বলা থাকে ডিগ্রিটি ইংরেজিতে পড়ানো হয়েছে। কিছু প্রোগ্রাম আইইএলটিএসের বদলে এটি গ্রহণ করে।', 'https://example.org/sample/glossary/moi', '2026-10-28', true, true, 'sample'),
  ('ielts', 'IELTS', 'আইইএলটিএস', 'An English test scored in bands from 0 to 9. Most master''s programs ask for 6.0 to 6.5.', '০ থেকে ৯ ব্যান্ডে নম্বর দেওয়া ইংরেজি পরীক্ষা। বেশিরভাগ মাস্টার্স প্রোগ্রাম ৬.০ থেকে ৬.৫ চায়।', 'https://example.org/sample/glossary/ielts', '2026-10-12', true, true, 'sample'),
  ('cgpa', 'CGPA', 'সিজিপিএ', 'Your cumulative grade point average. In Bangladesh it is usually out of 4.00; universities abroad may convert it to their own scale.', 'আপনার সামগ্রিক গ্রেড পয়েন্ট গড়। বাংলাদেশে সাধারণত ৪.০০-এর মধ্যে; বিদেশের বিশ্ববিদ্যালয় এটি নিজেদের স্কেলে রূপান্তর করতে পারে।', 'https://example.org/sample/glossary/cgpa', '2026-09-20', true, true, 'sample'),
  ('gpa-5', 'SSC/HSC GPA', 'এসএসসি/এইচএসসি জিপিএ', 'Your board exam result out of 5.00. Bachelor''s programs abroad use it for admission.', '৫.০০-এর মধ্যে আপনার বোর্ড পরীক্ষার ফল। বিদেশে ব্যাচেলর ভর্তিতে এটি দেখা হয়।', 'https://example.org/sample/glossary/gpa-5', '2026-08-24', true, true, 'sample'),
  ('three-year-bachelor', '3-year bachelor''s', '৩ বছরের ব্যাচেলর', 'Pass degrees and some programs in Bangladesh take 3 years. Some master''s programs abroad only accept 4-year degrees, so check before applying.', 'বাংলাদেশে পাস কোর্স ও কিছু প্রোগ্রাম ৩ বছরের। বিদেশের কিছু মাস্টার্স শুধু ৪ বছরের ডিগ্রি গ্রহণ করে, তাই আবেদনের আগে দেখে নিন।', 'https://example.org/sample/glossary/three-year-bachelor', '2026-10-28', true, true, 'sample'),
  ('provisional-certificate', 'Provisional certificate', 'প্রভিশনাল সার্টিফিকেট', 'A temporary certificate issued before the final degree certificate. Useful when results are delayed by session jam.', 'মূল সার্টিফিকেটের আগে দেওয়া অস্থায়ী সনদ। সেশনজটে ফল দেরি হলে এটি কাজে লাগে।', 'https://example.org/sample/glossary/provisional-certificate', '2026-10-12', true, true, 'sample'),
  ('session-jam', 'Session jam', 'সেশনজট', 'Delays that push a degree past its normal length. Universities abroad may ask why your study took longer.', 'যে দেরিতে ডিগ্রি স্বাভাবিক সময়ের চেয়ে লম্বা হয়ে যায়। বিদেশের বিশ্ববিদ্যালয় জানতে চাইতে পারে কেন পড়াশোনায় বেশি সময় লেগেছে।', 'https://example.org/sample/glossary/session-jam', '2026-09-20', true, true, 'sample'),
  ('attestation', 'Document attestation', 'কাগজপত্র সত্যায়ন', 'Official confirmation that your certificates are genuine, usually from the education board, ministry and embassy. Start early: it can take weeks.', 'আপনার সনদ আসল কি না তার আনুষ্ঠানিক নিশ্চয়তা, সাধারণত শিক্ষা বোর্ড, মন্ত্রণালয় ও দূতাবাস থেকে। আগে শুরু করুন: কয়েক সপ্তাহ লাগতে পারে।', 'https://example.org/sample/glossary/attestation', '2026-08-24', true, true, 'sample'),
  ('transcript', 'Transcript', 'ট্রান্সক্রিপ্ট', 'The official list of every course and grade in your degree, issued by your university.', 'আপনার ডিগ্রির প্রতিটি কোর্স ও গ্রেডের আনুষ্ঠানিক তালিকা, যা বিশ্ববিদ্যালয় দেয়।', 'https://example.org/sample/glossary/transcript', '2026-10-28', true, true, 'sample'),
  ('motivation-letter', 'Motivation letter', 'মোটিভেশন লেটার', 'A one- or two-page letter explaining why you want this program and how it fits your goals. Write a new one for each program.', 'এক-দুই পাতার চিঠি, যেখানে লিখবেন কেন এই প্রোগ্রাম চান আর এটি আপনার লক্ষ্যের সাথে কীভাবে মেলে। প্রতিটি প্রোগ্রামের জন্য আলাদা লিখুন।', 'https://example.org/sample/glossary/motivation-letter', '2026-10-12', true, true, 'sample'),
  ('lor', 'Letter of recommendation', 'রিকমেন্ডেশন লেটার', 'A letter from a teacher or employer about your abilities. Ask early and give them your CV.', 'আপনার যোগ্যতা নিয়ে শিক্ষক বা নিয়োগকর্তার চিঠি। আগেভাগে অনুরোধ করুন এবং তাঁদের আপনার সিভি দিন।', 'https://example.org/sample/glossary/lor', '2026-09-20', true, true, 'sample'),
  ('intake', 'Intake', 'ইনটেক', 'The month a program starts. Most European programs start in September or October; some also start in February or March.', 'যে মাসে প্রোগ্রাম শুরু হয়। ইউরোপের বেশিরভাগ প্রোগ্রাম সেপ্টেম্বর বা অক্টোবরে শুরু হয়; কিছু ফেব্রুয়ারি বা মার্চেও।', 'https://example.org/sample/glossary/intake', '2026-08-24', true, true, 'sample'),
  ('non-eu-seats', 'Non-EU seats', 'নন-ইইউ আসন', 'Places reserved for applicants from outside the EU, such as Bangladesh. When a university doesn''t publish the number, we show "Not published".', 'ইইউর বাইরের (যেমন বাংলাদেশের) আবেদনকারীদের জন্য সংরক্ষিত আসন। বিশ্ববিদ্যালয় সংখ্যা প্রকাশ না করলে আমরা "প্রকাশিত নয়" দেখাই।', 'https://example.org/sample/glossary/non-eu-seats', '2026-10-28', true, true, 'sample'),
  ('tuition-free', 'Tuition-free', 'টিউশন-ফ্রি', 'No tuition fee, but you still pay living costs and often a small semester fee.', 'টিউশন ফি নেই, তবে জীবনযাত্রার খরচ আর প্রায়ই সামান্য সেমিস্টার ফি দিতে হয়।', 'https://example.org/sample/glossary/tuition-free', '2026-10-12', true, true, 'sample'),
  ('semester-contribution', 'Semester contribution', 'সেমিস্টার কন্ট্রিবিউশন', 'A small fee German students pay each semester, often including a public transport ticket.', 'জার্মানিতে প্রতি সেমিস্টারে দেওয়া ছোট ফি, যাতে প্রায়ই গণপরিবহনের টিকিট থাকে।', 'https://example.org/sample/glossary/semester-contribution', '2026-09-20', true, true, 'sample'),
  ('blocked-account', 'Blocked account', 'ব্লকড অ্যাকাউন্ট', 'A German bank account holding a year of living costs that you can withdraw only monthly. Used as proof of funds for the visa.', 'জার্মান ব্যাংক অ্যাকাউন্ট, যেখানে এক বছরের খরচ জমা থাকে এবং মাসে মাসে তোলা যায়। ভিসার জন্য আর্থিক সামর্থ্যের প্রমাণ হিসেবে লাগে।', 'https://example.org/sample/glossary/blocked-account', '2026-08-24', true, true, 'sample'),
  ('uni-assist', 'uni-assist', 'ইউনি-অ্যাসিস্ট', 'A service many German universities use to check international applications before they decide. It charges a fee per application.', 'অনেক জার্মান বিশ্ববিদ্যালয় সিদ্ধান্তের আগে আন্তর্জাতিক আবেদন যাচাইয়ে এই সেবা ব্যবহার করে। প্রতি আবেদনে ফি লাগে।', 'https://example.org/sample/glossary/uni-assist', '2026-10-28', true, true, 'sample'),
  ('german-grade', 'German grade scale', 'জার্মান গ্রেড স্কেল', 'Germany grades from 1.0 (best) to 4.0 (pass). Universities convert your CGPA with a formula, so a lower German number is better.', 'জার্মানিতে গ্রেড ১.০ (সেরা) থেকে ৪.০ (পাস)। বিশ্ববিদ্যালয় সূত্র দিয়ে আপনার সিজিপিএ রূপান্তর করে, তাই জার্মান সংখ্যা যত কম তত ভালো।', 'https://example.org/sample/glossary/german-grade', '2026-10-12', true, true, 'sample'),
  ('dsu', 'DSU (right-to-study grant)', 'ডিএসইউ (রাইট-টু-স্টাডি গ্রান্ট)', 'Italy''s regional grants based on family income. They can cover tuition, a cash grant, meals and housing.', 'ইতালির আঞ্চলিক অনুদান, যা পরিবারের আয়ের ভিত্তিতে দেওয়া হয়। টিউশন, নগদ অনুদান, খাবার ও থাকার খরচ মেটাতে পারে।', 'https://example.org/sample/glossary/dsu', '2026-09-20', true, true, 'sample'),
  ('residence-permit', 'Residence permit', 'রেসিডেন্স পারমিট', 'Permission to live in the country for your studies. You usually apply soon after arrival, even if you entered with a visa.', 'পড়াশোনার জন্য দেশে থাকার অনুমতি। ভিসায় প্রবেশ করলেও সাধারণত পৌঁছানোর পর দ্রুত আবেদন করতে হয়।', 'https://example.org/sample/glossary/residence-permit', '2026-08-24', true, true, 'sample'),
  ('health-insurance', 'Health insurance', 'স্বাস্থ্যবীমা', 'Required for students in all three countries. Costs differ a lot: check what your city guide shows.', 'তিনটি দেশেই শিক্ষার্থীদের জন্য বাধ্যতামূলক। খরচে অনেক পার্থক্য: আপনার শহরের গাইডে দেখুন।', 'https://example.org/sample/glossary/health-insurance', '2026-10-28', true, true, 'sample'),
  ('conditional-offer', 'Conditional offer', 'শর্তসাপেক্ষ অফার', 'An admission that becomes final once you send a missing item, such as your final certificate or English score.', 'এমন ভর্তি, যা বাকি থাকা কিছু (যেমন চূড়ান্ত সনদ বা ইংরেজি স্কোর) পাঠালে চূড়ান্ত হয়।', 'https://example.org/sample/glossary/conditional-offer', '2026-10-12', true, true, 'sample'),
  ('application-fee', 'Application fee', 'আবেদন ফি', 'A fee paid when you apply, usually by international card or bank transfer from Bangladesh. It is rarely refunded.', 'আবেদনের সময় দেওয়া ফি, সাধারণত বাংলাদেশ থেকে আন্তর্জাতিক কার্ড বা ব্যাংক ট্রান্সফারে। সাধারণত ফেরত দেওয়া হয় না।', 'https://example.org/sample/glossary/application-fee', '2026-09-20', true, true, 'sample'),
  ('student-file', 'Student file', 'স্টুডেন্ট ফাইল', 'A file opened at a Bangladeshi bank so you can legally send tuition and living costs abroad.', 'বাংলাদেশি ব্যাংকে খোলা ফাইল, যাতে বৈধভাবে বিদেশে টিউশন ও জীবনযাত্রার খরচ পাঠাতে পারেন।', 'https://example.org/sample/glossary/student-file', '2026-08-24', true, true, 'sample')
