-- amarAbroad database, part 3 of 3: the Stage 1 sample data.
-- Generated by scripts/build-seed.mjs from data/*.json. Don't edit by hand: change the JSON and run npm run db:seed.
-- Paste into Supabase → SQL Editor → Run, after 01 and 02. Safe to run again (rows are updated in place).

begin;

-- fields: 27 rows
on conflict (slug) do update set name_en = excluded.name_en, name_bn = excluded.name_bn, field_group = excluded.field_group, tile = excluded.tile, published = excluded.published;

-- degree_mappings: 24 rows
on conflict (slug) do update set label_en = excluded.label_en, label_bn = excluded.label_bn, kind = excluded.kind, years = excluded.years, field = excluded.field, published = excluded.published;

-- exchange_rates: 2 rows
on conflict (currency) do update set bdt_per_unit = excluded.bdt_per_unit, updated_on = excluded.updated_on, source_url = excluded.source_url, last_verified = excluded.last_verified, is_sample = excluded.is_sample, published = excluded.published, origin = excluded.origin;

-- glossary_terms: 25 rows
on conflict (slug) do update set term = excluded.term, term_bn = excluded.term_bn, explain_en = excluded.explain_en, explain_bn = excluded.explain_bn, source_url = excluded.source_url, last_verified = excluded.last_verified, is_sample = excluded.is_sample, published = excluded.published, origin = excluded.origin;

commit;
